main() {
    loop {
        if ({{radar}}.scan() != null) {
            if ({{gun}}.ready()) {
                {{gun}}.shoot({{radar}}.scan().Angle())
            } else {
                if ({{radar}}.scan().Distance > 2) {
                    move({{radar}}.scan().Angle(), 0.3)
                } else {
                    move(0, 0)
                }
            }
        } else {
            move(0, 0)
        }
    }
}
